import sys

def is_triplet_exist(triplet_list, edge_list):
    """Check if there exists a triplet in the triplet list that can be formed by the edge_list."""
    triplet_set = set()
    for triplet in triplet_list:
        for edge in edge_list:
            if triplet[0] == edge[0] and triplet[1] in [edge[1], edge[0]]:
                triplet_set.add(triplet)
                break
    return triplet_set

def is_no_triplet_exist(triplets, edge_list):
    """Check a list of triplets and ensure no triplet intersects with given edge list."""
    for triplet in triplets:
        for edge in edge_list:
            intersection = set()
            for inter in edge:
                if inter in triplet:
                    intersection.add(frozenset(triplet))
            if len(intersection) > 1:
                return False
    return True

# Main function to solve the problem
def solve(tree_n):
    triplets = [[] for _ in range(n)]
    for edge in edge_list:
        triplets[edge[0]].append(frozenset([edge[0], edge[1]]))
        triplets[edge[1]].append(frozenset([edge[1], edge[0]]))

    possible_triplets = triplets[1]
    for triplet_row in triplets[2]:
        if not is_triplet_exist(possible_triplets, edge_list):
            possible_triplets.append(triplet_row)
        else:
            break

    if len(possible_triplets) == (n - 1) // 3:
