import sys

def can_transform(a, b):
    if len(a) != len(b):
        return False
    if a == b:
        return True
    a = str(a)
    b = str(b)
    n = 0
    if b[0] < b[len(b) - 1]:
        n = 1
    for i in range(len(a) - 1):
        if (n % 2 == 0 and int(a[i]) < int(a[i + 1])) or (n % 2 == 1 and int(a[i]) > int(a[i + 1])):
            n += 1
    if n % 2 == 0 and a[-1] == str(0) or (n % 2 == 1 and b[-1] == str(9)):
        return True
    return False

def find_transformations(a, b, depth=0):
    if depth == len(a) - 1:
        if can_transform(int(a), int(b)):
            return 0 if depth % 2 == 0 else 1
        return float('inf')
    min_coins = float('inf')
    min_operations = float('inf')
    if a[depth] > b[depth]:
        min_coins = 1 + find_transformations(a[:depth + 1] + "9" + a[depth + 1:], b[:depth + 1] + b[depth + 1:], depth + 1)
    if a[depth] < b[depth]:
        min_coins = 1 + find_transformations(a[:depth + 1] + "0" + a[depth + 1:], b[:depth + 1] + b[depth + 1:], depth + 1)
    if min_coins == float('inf'):
        return min_coins
    return min(min_coins, find_transformations(a, b, depth + 1))

n = int(input().strip())
a = int(input().strip())
b = int(input().strip())

if can_transform(a, b):
    print(find_transformations(a, b))
else:
