from collections import defaultdict

def calculate_substring_count(strings, k):
    n, m = len(strings), len(max(strings, key=len))
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    counts = defaultdict(int)

    for length in range(m + 1):
        for i in range(n):
            if i > 0:
                dp[i][length] = min(dp[i - 1][length], dp[i][length - 1]) + 1
            counts[strings[i][0:length]] += dp[i][length]

    result = [0] * n
    for sequence, freq in counts.items():
        total = 0
        for i in range(m, -1, -1):
            for j in range(min(m, len(sequence) + i), i + 1, -1):
                total += 1
                result[j - i] = frequencies[sequence[j - i:i + j - i - 1]] = max(total, freq)
                if total == k:
                    return result

    return result

