def check_cnf(clauses, variables):
    cnf_clauses = defaultdict(list)
    for clause in clauses:
        for variable in clause:
            cnf_clauses[variable].append(True)
        cnf_clauses[len(cnf_clauses) + 1].append(False)

    cnf_clauses.update({k + 2 * m: v for v, k in cnf_clauses.items()})
    cnf_clauses.update({k + 2: v for v, k in cnf_clauses.items()})

    for i, literal in enumerate(cnf_clauses.keys()):
        if literal < 0:
            var = -literal
            cnf_clauses[literal + 2 * m][var - 1] = True
            cnf_clauses[literal + 2][m - abs(var) - 1] = True
        else:
            cnf_clauses[literal + 2 * m][literal - 1] = True
            cnf_clauses[literal + 2][m - literal] = True

    positive_clauses = [v for k, v in cnf_clauses.items() if k & m]
    for positive_clause in positive_clauses:
        if any(cnf_clauses[i] for i in positive_clause):
            return "NO"
        elif not any(~cnf_clauses[i] for i in positive_clause):
            return "NO"

