    min_diff = float('inf')

    def binary_search(low, high):
        """
        Performs binary search to find the minimum possible difference.
        """
        while low < high:
            mid = (low + high) // 2
            if is_valid(visited, shops, mid):
                high = mid
            else:
                low = mid + 1

        return low

    def is_valid(visited, shops, price):
        """
        Checks if there is an invalid range present.
        """
        for i in range(1, visited + 1):
            for j in range(i + 1, visited + 1):
                if j - i == price:
                    return True
                elif j - i < price and shops[i - 1] < shops[j - 1] and (shops[i - 1] < shops[k] < shops[j - 1] or shops[j - 1] < shops[k] < shops[i - 1]) for k in range(i, j):
                    return True
        return False

    return binary_search(1, len(shops) - 1)

