def split_segment_costs(arr):
    n = len(arr)
    freq = [0] * n
    for i in range(n):
        freq[arr[i]] += 1

    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(i + 1):
            if freq[i] > j:
                dp[i][j] = dp[i - 1][j]
            elif freq[i] > j and freq[i] < 2 * j:
                dp[i][j] = dp[i - 1][j - freq[i]] + freq[i] + abs(2 * j - freq[i])
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[-1][-1]

