from heapq import heappush, heappop

def dijkstra(graph, start, n, d):
    vertices = {i: float('inf') for i in graph}
    vertices[start] = 0
    pq = [(0, start)]

    while pq:
        cost, vertex = heappop(pq)
        if vertices[vertex] < cost:
            continue
        for neighbor, weight in graph[vertex].items():
            if vertices[neighbor] > cost + weight:
                vertices[neighbor] = cost + weight
                heappush(pq, (vertices[neighbor], neighbor))

    return [vertices[i] if i in vertices else float('inf') for i in range(1, n+1) if sum(d[:k]) < i <= sum(d[:k+1])]

def maximize_agents(graph, start, n, d):
    sorted_deg = [-d[i] for i in range(k)]
    degree_sequence = set(sorted_deg)
    viable_agents = [i for i in range(1, n+1) if sorted_deg.count(min(degree_sequence)) <= graph[i].keys().__len__() / n]
    sorted_deg.sort()
    for agent in viable_agents:
        degree_sequence.remove(min(degree_sequence))
    connectivity = defaultdict(set)
    for u, v in graph:
        connectivity[u].add(v)
        connectivity[v].add(u)
    info = [0] * (n+1)
    for i, deg in enumerate(viable_agents):
        for nxt in connectivity[i]:
            if d[nxt-1] > deg:
                info[nxt] = 50000000  # Infinite
            elif info[nxt] <= deg:
                info[nxt] = min(info[nxt], deg)
    agents = [viable_agents[i] for i, deg in enumerate(info) if deg >= d[i]]
    return dijkstra(graph, start, n, info)
