from collections import defaultdict

def parse_clauses(n, m, clauses, literals):
    clauses_dict = defaultdict(list)

    for i in range(n):
        k = int(clauses[i][0])
        clause = clauses[i][1:]
        for j in range(k):
            literal = int(clause[j])
            if literal < 0:
                # Convert the negative literal to a positive equivalent
                negated_variable = -1 * (-1 * literal - 1)
                clauses_dict[negated_variable].append((i, 1))
            else:
                clauses_dict[literal].append((i, 0))

    return clauses_dict

def find_satisfying_assignment(q,n,l, clauses_dict):
    # Build a dependent edges graph
    authorized_edges = {}

    for variable in q:
        authorized_edges[variable] = []

    # Add directly dependent edges
    for word in q:
        assigned = False
        for clause_number, operation, item in clauses_dict[word]:
            try:
                if l[abs(int(item))] == 1:
                    authorized_edges[int(word)].append(clause_number)
                elif l[abs(int(item))] == -1:
                    authorized_edges[int(word)].append(-1 * clause_number)
                assigned = True
            except:
                # Handling IndexError for negative indices
                if int(item) < 0:
                    # Convert negative variable to positive
                    negated_variable = -1 * (-1 * int(item) - 1)
                    authorized_edges[int(word)].append(clause_number)
                    authorized_edges[negated_variable].append(-1 * clause_number)
                else:
                    authorized_edges[int(word)].append(abs(int(item)))

        if not assigned:
            return None

    t = set()

    for word in authorized_edges:
        t |= authorized_edges[word]
        reversed_word = -1 * word

        if word == -1 * reversed_word:
            continue

        if reversed_word in authorized_edges and authorized_edges[reversed_word] >= t:
            t -= authorized_edges[reversed_word]
            authorized_edges[word] |= t

        if authorized_edges[reversed_word] > t:
            break

    return list(t)

