from collections import defaultdict
from functools import reduce

def calculate_cost(subsegment):
    cost, max_count = 0, defaultdict(int)
    for i, num in enumerate(subsegment):
        max_count[num] += 1
        if max_count[num] == 2:
            cost += 1

    return cost

def min_cost_possible(n, k, segment):
    segments_costs = [0] * k
    memo = {}

    def dp(current_idx, taken_segments):
        if (current_idx, taken_segments) in memo:
            return memo[(current_idx, taken_segments)]

        if current_idx == n or taken_segments == k - 1:
            return float('inf')

        subsegment = segment[current_idx:]
        costs = [calculate_cost(subsegment[:i]) + i - current_idx + dp(i + 1, taken_segments + 1) + memo[(current_idx + 1, taken_segments)]
                 for i in range(len(subsegment) + 1)]

        memo[(current_idx, taken_segments)] = min(costs)
        return costs[min(range(len(costs)), key=lambda x: costs[x])]

    if not dp(0, 0):
        return float('inf')

    total_cost = sum(costs) + (k - 1)**2
    if total_cost != dp(0, 0):
        return float('inf')

    return min_cost_possible_helper(k)

def min_cost_possible_helper(k):
    memo = defaultdict(lambda: defaultdict(lambda: float('inf')))
    memo[0][0] = 0  # No operations, total segmented to prepare
    memo[1][1] = calculate_cost([1, 2, 3])

    def dfs(prev_k, count, op_cost):
        if count == k:
            memo[prev_k][op_cost] = min(memo[prev_k][op_cost], total_cost)
        else:
            for i in range(1, max(0, count + 1 - 2 * (k - prev_k))):
                prev_cost = memo[prev_k][op_cost]
                for j in range(i, min(len(segment), j + 1)):
                    ops_cost = op_cost + i - j
                    memo[prev_k + 1][ops_cost] = min(memo[prev_k + 1][ops_cost], prev_cost + calculate_cost(segment[j:i + 1]))
                    memo[prev_k + 1][ops_cost] = min(memo[prev_k + 1][ops_cost], prev_cost + 1 + i - (count + 1))

    total_cost = dp(0, 0)

    for op_cost in range(1, total_cost + 1):
        op_cost += (k - prev_k) * 2

        dfs(0, 0, op_cost)

    return memo[k-1][total_cost]

